// Package gtkcss keeps a block of palette colours in the user's GTK 3 and
// GTK 4 gtk.css (libadwaita named colours and CSS variables), between marker
// comments so everything outside it is left alone.
//
// A gtk.css that is a symlink (a theme's file linked in) becomes a file that
// @imports the link's target, then the block; Remove puts the link back. A
// file generated by iNiR (overwritten by it on every wallpaper change) is
// backed up to gtk.css.ano-backup and replaced; Remove puts it back.
package gtkcss

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const (
	begin    = "/* >>> AnoShell colours: generated, edits inside are replaced >>> */"
	end      = "/* <<< AnoShell colours <<< */"
	linkNote = "/* AnoShell: this file was a link to "
	inir     = "Generated with iNiR theming"
)

// Named colour -> palette role (colors.json keys).
var named = [][2]string{
	{"accent_color", "primary"},
	{"accent_bg_color", "primary"},
	{"accent_fg_color", "on_primary"},
	{"window_bg_color", "surface"},
	{"window_fg_color", "on_surface"},
	{"view_bg_color", "surface"},
	{"view_fg_color", "on_surface"},
	{"headerbar_bg_color", "surface_container"},
	{"headerbar_fg_color", "on_surface"},
	{"headerbar_backdrop_color", "surface"},
	{"sidebar_bg_color", "surface_container_low"},
	{"sidebar_fg_color", "on_surface"},
	{"card_bg_color", "surface_container"},
	{"card_fg_color", "on_surface"},
	{"popover_bg_color", "surface_container_high"},
	{"popover_fg_color", "on_surface"},
	{"dialog_bg_color", "surface_container_high"},
	{"dialog_fg_color", "on_surface"},
	{"destructive_color", "error"},
	{"destructive_bg_color", "error"},
	{"destructive_fg_color", "on_error"},
	// GTK 3 themes' names
	{"theme_bg_color", "surface"},
	{"theme_fg_color", "on_surface"},
	{"theme_base_color", "surface"},
	{"theme_text_color", "on_surface"},
	{"theme_selected_bg_color", "primary"},
	{"theme_selected_fg_color", "on_primary"},
}

// Block is the marked block for colours (role -> hex). GTK 4 also gets
// libadwaita's CSS variables (1.6+), which GTK 3 can't parse.
func Block(colors map[string]string, gtk4 bool) string {
	var b strings.Builder
	b.WriteString(begin + "\n")
	var vars []string
	for _, n := range named {
		c := colors[n[1]]
		if c == "" {
			continue
		}
		fmt.Fprintf(&b, "@define-color %s %s;\n", n[0], c)
		if !strings.HasPrefix(n[0], "theme_") {
			vars = append(vars, fmt.Sprintf("  --%s: %s;\n", strings.ReplaceAll(n[0], "_", "-"), c))
		}
	}
	if gtk4 && len(vars) > 0 {
		fmt.Fprintf(&b, ":root {\n%s}\n", strings.Join(vars, ""))
	}
	return b.String() + end + "\n"
}

// strip returns s without the block.
func strip(s string) string {
	i := strings.Index(s, begin)
	if i < 0 {
		return s
	}
	j := strings.Index(s[i:], end)
	if j < 0 {
		return s[:i]
	}
	rest := strings.TrimPrefix(s[i+j+len(end):], "\n")
	return s[:i] + rest
}

// Apply writes block into dir/gtk.css.
func Apply(dir, block string) error {
	path := filepath.Join(dir, "gtk.css")
	body := ""
	fi, err := os.Lstat(path)
	switch {
	case err == nil && fi.Mode()&os.ModeSymlink != 0:
		target, err := os.Readlink(path)
		if err != nil {
			return err
		}
		if !filepath.IsAbs(target) {
			target = filepath.Join(dir, target)
		}
		body = linkNote + target + " */\n@import url(\"file://" + target + "\");\n"
	case err == nil:
		b, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		body = strip(string(b))
		if strings.Contains(body, inir) {
			if _, err := os.Stat(path + ".ano-backup"); os.IsNotExist(err) {
				if err := os.WriteFile(path+".ano-backup", []byte(body), 0o644); err != nil {
					return err
				}
			}
			body = ""
		}
	case !os.IsNotExist(err):
		return err
	}
	if strings.TrimSpace(body) != "" {
		body = strings.TrimRight(body, "\n") + "\n\n"
	} else {
		body = ""
	}
	return write(dir, path, body+block)
}

// Remove takes the block out of dir/gtk.css: a file that was a link becomes
// the link again, one left empty gets its backed-up content back (iNiR's) or
// is deleted.
func Remove(dir string) error {
	path := filepath.Join(dir, "gtk.css")
	fi, err := os.Lstat(path)
	if err != nil || fi.Mode()&os.ModeSymlink != 0 {
		return nil
	}
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if !strings.Contains(string(b), begin) {
		return nil
	}
	body := strip(string(b))
	if strings.HasPrefix(body, linkNote) {
		head, rest, _ := strings.Cut(body, "\n")
		_, rest, _ = strings.Cut(rest, "\n") // the @import
		if strings.TrimSpace(rest) == "" {
			target := strings.TrimSuffix(strings.TrimPrefix(head, linkNote), " */")
			if err := os.Remove(path); err != nil {
				return err
			}
			return os.Symlink(target, path)
		}
	}
	if strings.TrimSpace(body) == "" {
		if _, err := os.Stat(path + ".ano-backup"); err == nil {
			return os.Rename(path+".ano-backup", path)
		}
		return os.Remove(path)
	}
	return write(dir, path, strings.TrimRight(body, "\n")+"\n")
}

func write(dir, path, data string) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, ".gtk.css-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.WriteString(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp.Name(), 0o644); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path) // replaces a symlink itself, not its target
}
